func (p *Program) runFileInPlace(path string) error {
	in, err := os.ReadFile(path) // #nosec G304
	if err != nil {
		return err
	}

	out := new(bytes.Buffer)

	err = p.Fn(bytes.NewReader(in), out)
	if err != nil {
		return err
	}

	return os.WriteFile(path, out.Bytes(), 0o600)
}
